BEGIN; SET LOCAL statement_timeout='1s'; SET LOCAL lock_timeout='500ms';
DO $reconcile$ BEGIN
 IF NOT pg_try_advisory_xact_lock(hashtextextended('comparator_strict:atomic-v1',0)) THEN RAISE EXCEPTION 'ce200_busy'; END IF;
 IF EXISTS(SELECT 1 FROM pg_stat_activity WHERE cardinality(pg_blocking_pids(pid))>0 OR (pid<>pg_backend_pid() AND state='active' AND query_start<clock_timestamp()-interval '30 seconds')) THEN RAISE EXCEPTION 'ce200_unhealthy'; END IF;
 UPDATE comparator_strict.execution_jobs SET status='rolled_back',finished_at=clock_timestamp(),stop_reason='CE200 census cancelled by 5s statement_timeout; read-only catalogue payload rolled back, reservation retained; reviewed lighter query next.',receipt='{"status":"payload_cancelled","sqlstate":"57014","catalog_writes":0,"reservation_retained":true}'::jsonb
 WHERE job_key='ce1-ce200-04b0acb423d0e2d372e384c1eb3d' AND operation_hash='04b0acb423d0e2d372e384c1eb3d34d2526fc7587037ead7d4b520e02bc8c673' AND status='running' AND receipt IS NULL;
 IF NOT FOUND THEN RAISE EXCEPTION 'ce200_unexpected_job_state'; END IF;
 UPDATE comparator_strict.execution_budget SET sql_ms_reserved=sql_ms_reserved+3000,read_rows_reserved=read_rows_reserved+10,bytes_reserved=bytes_reserved+16384,write_rows_reserved=write_rows_reserved+2,updated_at=clock_timestamp() WHERE project_ref='gkffvigcnsesbaihycay' AND budget_date='2026-09-03';
END $reconcile$;
SELECT jsonb_build_object('job',(SELECT to_jsonb(j) FROM comparator_strict.execution_jobs j WHERE job_key='ce1-ce200-04b0acb423d0e2d372e384c1eb3d'),'budget',(SELECT to_jsonb(b) FROM comparator_strict.execution_budget b WHERE budget_date='2026-09-03'),'unresolved',(SELECT count(*) FROM comparator_strict.execution_jobs WHERE status IN ('planned','running','halted','unknown'))) AS evidence;
COMMIT;
